    # Truncate at 200 records
    records = scholarships_data[:200]

    added = 0
    skipped_dup = 0
    errors = []

    for rec in records:
        record = dict(rec)
        record.setdefault("source", "global_discovery")
        record.setdefault("source_id", f"manual_{datetime.now(timezone.utc).strftime('%Y%m%d')}_{len(records):03d}")
        record.setdefault("status", "active")
        record.setdefault("active", 1)
        if not record.get("scholarship_name"):
            continue
        if not record.get("organization"):
            record["organization"] = "Unknown"
        if not record.get("amount_display") and record.get("amount_min") is not None:
            mn = record["amount_min"]
            mx = record.get("amount_max")
            if mn == mx:
                record["amount_display"] = f"${mn:,}"
            elif mx:
                record["amount_display"] = f"${mn:,} - ${mx:,}"
            else:
                record["amount_display"] = f"${mn:,}+"
        if not record.get("application_url"):
            record["application_url"] = ""
            record["link_notes"] = "no application URL provided; manual entry"

        inserted = False
        for db_path in DB_PATHS:
            conn = sqlite3.connect(db_path)
            try:
                if is_dup(conn, record):
                    skipped_dup += 1
                    continue
                insert(conn, record)
                added += 1
                inserted = True
            except Exception as e:
                errors.append(str(e))
            finally:
                conn.close()

    print(f"Added: {added} | Skipped (dup): {skipped_dup} | Errors: {len(errors)}")
    print(f"Target: 200 | Remaining gap: {200 - added}")
    for p in DB_PATHS:
        c = sqlite3.connect(p)
        after = c.execute("SELECT COUNT(*) FROM scholarships").fetchone()[0]
        print(f"{p}: {before_stats[p]} -> {after}")
        c.close()

